<?php
namespace App\Http\Controllers;
use App\Models\{Personnel,PersonnelType,Warehouse}; use Illuminate\Http\{Request,RedirectResponse}; use Illuminate\Validation\Rule; use Illuminate\View\View;
class PersonnelController extends Controller { public function index(): View { return view('personnel.index',['personnel'=>Personnel::latest()->paginate(15)]); } public function create(): View{return view('personnel.create',$this->formData(new Personnel));} public function store(Request $r): RedirectResponse{Personnel::create($this->rules($r));return redirect()->route('personnel.index')->with('success','Personnel created successfully.');} public function show(Personnel $personnel): View{return view('personnel.show',compact('personnel'));} public function edit(Personnel $personnel): View{return view('personnel.edit',$this->formData($personnel));} public function update(Request $r,Personnel $personnel): RedirectResponse{$personnel->update($this->rules($r,$personnel));return redirect()->route('personnel.index')->with('success','Personnel updated successfully.');} private function formData(Personnel $p):array{return ['personnel'=>$p,'personnelTypes'=>PersonnelType::where('is_active',1)->orderBy('personnel_type')->get(),'warehouses'=>Warehouse::where('is_active',1)->orderBy('warehouse_code')->get()];} private function rules(Request $r,?Personnel $p=null):array{return $r->validate(['employee_id'=>['required','string','max:50',Rule::unique('personnel','employee_id')->ignore($p)],'last_name'=>'required|string|max:100','first_name'=>'required|string|max:100','middle_name'=>'nullable|string|max:100','address'=>'required|string','contact_number'=>'required|string|max:50','position'=>'required|string|max:100','personnel_type'=>['required',Rule::exists('personnel_types','personnel_type')],'warehouse_code'=>['required',Rule::exists('warehouses','warehouse_code')],'drivers_license'=>'nullable|string|max:100','is_mechanic'=>'required|boolean','is_active'=>'required|boolean','remarks'=>'nullable|string']);} }
